package com.quizmaster;

import com.quizmaster.model.*;
import com.quizmaster.security.*;
import com.quizmaster.service.*;
import com.quizmaster.storage.*;
import com.quizmaster.ui.NavigationPolicy;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;

/** Dependency-free account, subject isolation, and migration checks for updated Phase 7. */
public final class Phase7Tests {
    private static int passed;
    public static void main(String[] args)throws Exception{
        if(args.length==2&&args[0].equals("verify-account")){StudentProfileStore st=new StudentProfileStore(Path.of(args[1]));TeacherAccountStore tt=new TeacherAccountStore(Path.of(args[1]));if(st.authenticate("S-100","NewLearner@456".toCharArray())==null||st.authenticate("STU1002","GeneratedStudent@123".toCharArray())==null||tt.authenticate("TCH1001","NewTeacher@456".toCharArray())==null||tt.authenticate("TCH1002","InviteTeacher@123".toCharArray())==null)throw new AssertionError("persisted account could not authenticate");System.out.println("PASS: account credentials reload in a fresh JVM");return;}
        if(args.length==3&&args[0].equals("use-invitation")){TeacherAccountStore tt=new TeacherAccountStore(Path.of(args[1]));TeacherProfile created=tt.registerWithCode("Invited Teacher","InviteTeacher@123".toCharArray(),"InviteTeacher@123".toCharArray(),args[2]);if(!created.getTeacherId().equals("TCH1002")||tt.authenticate(created.getTeacherId(),"InviteTeacher@123".toCharArray())==null)throw new AssertionError("persisted invitation could not be used");System.out.println("PASS: persisted invitation was accepted in a fresh JVM");return;}
        if(args.length==1&&args[0].equals("verify-live-demo")){StudentProfileStore st=new StudentProfileStore(Path.of("data"));TeacherAccountStore tt=new TeacherAccountStore(Path.of("data"));QuestionLoadResult q=new QuestionStore(Path.of("data")).load();ResultLoadResult r=new ResultStore(Path.of("data")).loadAll();if(st.authenticate("STU1001","Student@123".toCharArray())==null||tt.authenticate("TCH1001","Teacher@123".toCharArray())==null)throw new AssertionError("demo account authentication failed");if(!q.isClean()||q.getQuestions().size()!=5||q.getQuestions().stream().anyMatch(x->!x.getSubjectId().equals(Subject.OOP_ID)))throw new AssertionError("live OOP questions did not remain associated");if(!r.isClean()||!r.getResults().isEmpty())throw new AssertionError("unexpected result records");System.out.println("PASS: live demo accounts authenticate; five OOP questions are preserved; no result rows were added");return;}
        Path root=Files.createTempDirectory(Path.of("build"),"phase7-");
        try{accounts(root.resolve("accounts"));invitationChecks(root.resolve("invitations"));subjectsAndScopes(root.resolve("subjects"));migrations(root.resolve("migration"));System.out.println("Phase 7 checks passed: "+passed);}
        finally{try(var walk=Files.walk(root)){walk.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.deleteIfExists(p);}catch(Exception ignored){}});}}
    }
    private static void accounts(Path dir)throws Exception{
        check(NavigationPolicy.afterLogin(Role.STUDENT).equals(NavigationPolicy.STUDENT_SUBJECTS),"student login route always opens subject selection");check(NavigationPolicy.afterLogin(Role.TEACHER).equals(NavigationPolicy.TEACHER_SUBJECTS),"teacher login opens owned-subject workspace");check(NavigationPolicy.registrationFor(Role.STUDENT).equals(NavigationPolicy.STUDENT_REGISTER)&&NavigationPolicy.registrationFor(Role.TEACHER).equals(NavigationPolicy.TEACHER_REGISTER),"each login has a dedicated registration route");
        StudentProfileStore students=new StudentProfileStore(dir);char[] sp="Learner@123".toCharArray();StudentProfile p=students.register("Nina, Student","S-100",sp,sp);
        students.ensureDemoAccount("STU1001","Existing demo","Student@123".toCharArray());check(students.authenticate("STU1001","Student@123".toCharArray())!=null,"existing demo student account authenticates");StudentProfile generatedStudent=students.registerGenerated("Generated student","GeneratedStudent@123".toCharArray(),"GeneratedStudent@123".toCharArray());StudentProfile generatedStudent2=students.registerGenerated("Generated student 2","Generated2@123".toCharArray(),"Generated2@123".toCharArray());check(generatedStudent.getStudentId().equals("STU1002")&&generatedStudent2.getStudentId().equals("STU1003"),"student IDs are generated uniquely from saved accounts");var idPool=java.util.concurrent.Executors.newFixedThreadPool(2);try{var one=idPool.submit(()->new StudentProfileStore(dir).registerGenerated("Concurrent one","ConcurrentOne@123".toCharArray(),"ConcurrentOne@123".toCharArray()).getStudentId());var two=idPool.submit(()->new StudentProfileStore(dir).registerGenerated("Concurrent two","ConcurrentTwo@123".toCharArray(),"ConcurrentTwo@123".toCharArray()).getStudentId());check(!one.get().equals(two.get()),"concurrent student registrations receive distinct IDs");}finally{idPool.shutdownNow();}
        check(students.authenticate("s-100","Learner@123".toCharArray())!=null,"student registration stores a verifiable account");check(students.authenticate("S-100","Wrong@123".toCharArray())==null,"incorrect student password rejected");expect(IllegalArgumentException.class,()->students.register("Other","s-100",sp,sp),"duplicate student ID rejected");expect(IllegalArgumentException.class,()->students.register("Bad","S-101","weak".toCharArray(),"weak".toCharArray()),"weak password rejected");
        String csv=Files.readString(dir.resolve("students.csv"),StandardCharsets.UTF_8);check(!csv.contains("Learner@123")&&!csv.contains("Student@123"),"student passwords are not stored in plain text");SessionManager sessions=new SessionManager();StudentProfileService service=new StudentProfileService(students,sessions);service.registerGenerated("No auto sign-in","NoAuto@123".toCharArray(),"NoAuto@123".toCharArray());check(sessions.current()==null,"student registration never creates an authenticated session");check(service.login("S-100",sp),"student login succeeds");char[] changed="NewLearner@456".toCharArray();service.changePassword(sp,changed,changed);check(students.authenticate("S-100",changed)!=null&&students.authenticate("S-100",sp)==null,"student can change own password");sessions.clear();check(sessions.current()==null,"logout clears active student session");check(new StudentProfileStore(dir).authenticate("S-100",changed)!=null,"student persistence reloads in a new store instance");
        students.ensureDemoAccount("S-DEMO","Original Demo","DemoStudent@123".toCharArray());students.ensureDemoAccount("S-DEMO","Overwritten","OtherStudent@123".toCharArray());check(students.authenticate("S-DEMO","DemoStudent@123".toCharArray())!=null&&students.authenticate("S-DEMO","OtherStudent@123".toCharArray())==null,"student demo seed never overwrites an existing account");TeacherAccountStore teachers=new TeacherAccountStore(dir);teachers.ensureDemoAccount("TCH1001","Demo Teacher","Teacher@123".toCharArray());teachers.ensureDemoAccount("TCH1001","Changed","Changed@456".toCharArray());check(teachers.authenticate("TCH1001","Teacher@123".toCharArray())!=null,"teacher demo seeded only once and password preserved");check(teachers.authenticate("TCH1001","Changed@456".toCharArray())==null,"demo reseed never overwrites password");expect(IllegalArgumentException.class,()->teachers.register("Duplicate","tch1001","ValidPass@123".toCharArray(),"ValidPass@123".toCharArray()),"duplicate teacher ID rejected");TeacherService ts=new TeacherService(teachers,students,sessions);expect(SecurityException.class,ts::createTeacherRegistrationCode,"teacher registration invitation requires authenticated teacher");check(ts.login("TCH1001","Teacher@123".toCharArray()),"teacher ID/password login succeeds");String invite=ts.createTeacherRegistrationCode();TeacherProfile generatedTeacher=ts.registerTeacherWithCode("Invited Teacher","InviteTeacher@123".toCharArray(),"InviteTeacher@123".toCharArray(),invite);TeacherProfile generatedTeacher2=ts.registerTeacherWithCode("Invited Teacher 2","InviteTwo@123".toCharArray(),"InviteTwo@123".toCharArray(),ts.createTeacherRegistrationCode());check(generatedTeacher.getTeacherId().equals("TCH1002")&&generatedTeacher2.getTeacherId().equals("TCH1003"),"teacher IDs are generated uniquely for one-use invitations");expect(SecurityException.class,()->ts.registerTeacherWithCode("Replay","ReplayPass@123".toCharArray(),"ReplayPass@123".toCharArray(),invite),"teacher invitation codes cannot be reused");String invitationCsv=Files.readString(dir.resolve("teacher-invitations.csv"));check(!invitationCsv.contains(invite),"teacher invitations are stored as hashes, not plain codes");char[] tc="Teacher@123".toCharArray(),tn="NewTeacher@456".toCharArray();ts.changePassword(tc,tn,tn);check(teachers.authenticate("TCH1001",tn)!=null&&teachers.authenticate("TCH1001",tc)==null,"teacher can change own password");Process child=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin","java.exe").toString(),"-cp",System.getProperty("java.class.path"),Phase7Tests.class.getName(),"verify-account",dir.toAbsolutePath().toString()).redirectErrorStream(true).start();if(!child.waitFor(15,java.util.concurrent.TimeUnit.SECONDS)){child.destroyForcibly();throw new AssertionError("fresh JVM account check timed out");}String childOutput=new String(child.getInputStream().readAllBytes(),StandardCharsets.UTF_8);if(child.exitValue()!=0)throw new AssertionError("fresh JVM account check failed: "+childOutput);check(childOutput.contains("PASS:"),"student and teacher credentials persist across a fresh JVM");sessions.clear();check(!ts.login("TCH1001","Wrong@123".toCharArray())&&sessions.current()==null,"incorrect teacher password leaves no session");check(!Files.readString(dir.resolve("teachers.csv")).contains("Teacher@123"),"teacher password is not stored in plain text");
    }
    private static void invitationChecks(Path dir)throws Exception{
        Files.createDirectories(dir);StudentProfileStore students=new StudentProfileStore(dir);TeacherAccountStore teachers=new TeacherAccountStore(dir);teachers.ensureDemoAccount("TCH1001","Issuing Teacher","IssuerPass@123".toCharArray());SessionManager sessions=new SessionManager();TeacherService service=new TeacherService(teachers,students,sessions);
        expect(SecurityException.class,service::createTeacherRegistrationCode,"invitation creation is denied without an authenticated teacher");
        sessions.startStudent(new StudentProfile("S-INVITE","Student"));expect(SecurityException.class,service::createTeacherRegistrationCode,"students cannot issue teacher invitations");
        check(service.login("TCH1001","IssuerPass@123".toCharArray()),"issuing teacher can authenticate before generating invitation");String first=service.createTeacherRegistrationCode(),second=service.createTeacherRegistrationCode();check(!first.equals(second),"teacher invitation codes are unique");
        expect(SecurityException.class,()->service.registerTeacherWithCode("Invalid Invite","InvalidInvite@123".toCharArray(),"InvalidInvite@123".toCharArray(),"invalid-code"),"invalid invitation code is rejected");
        String saved=Files.readString(dir.resolve("teacher-invitations.csv"),StandardCharsets.UTF_8);check(saved.contains("TCH1001")&&!saved.contains(first)&&!saved.contains(second),"invitation file stores issuing teacher IDs and hashes, never raw codes");
        Process child=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin","java.exe").toString(),"-cp",System.getProperty("java.class.path"),Phase7Tests.class.getName(),"use-invitation",dir.toAbsolutePath().toString(),first).redirectErrorStream(true).start();if(!child.waitFor(15,java.util.concurrent.TimeUnit.SECONDS)){child.destroyForcibly();throw new AssertionError("fresh JVM invitation check timed out");}String output=new String(child.getInputStream().readAllBytes(),StandardCharsets.UTF_8);if(child.exitValue()!=0)throw new AssertionError("fresh JVM invitation check failed: "+output);check(output.contains("PASS:"),"unused teacher invitation persists and succeeds after restart");
        expect(SecurityException.class,()->service.registerTeacherWithCode("Replay","ReplayPass@123".toCharArray(),"ReplayPass@123".toCharArray(),first),"used invitation cannot be reused");TeacherProfile created=service.registerTeacherWithCode("Second Invite","SecondInvite@123".toCharArray(),"SecondInvite@123".toCharArray(),second);check(created.getTeacherId().equals("TCH1003"),"a separate unused invitation remains usable");
        saved=Files.readString(dir.resolve("teacher-invitations.csv"),StandardCharsets.UTF_8);check(!saved.contains(first)&&!saved.contains(second),"used invitation records continue to store only hashes");
    }
    private static void subjectsAndScopes(Path dir)throws Exception{
        Files.createDirectories(dir);Path emptyDir=dir.resolve("empty");Files.createDirectories(emptyDir);SessionManager emptySessions=new SessionManager();emptySessions.startStudent(new StudentProfile("E1","Empty"));check(new SubjectService(new SubjectStore(emptyDir),emptySessions).activeForStudent().isEmpty(),"empty active-subject list has a true empty state");emptySessions.clear();SessionManager sessions=new SessionManager();StudentProfileStore ss=new StudentProfileStore(dir);TeacherAccountStore ts=new TeacherAccountStore(dir);ts.ensureDemoAccount("T1","Owner One","Owner@1234".toCharArray());ts.ensureDemoAccount("T2","Owner Two","Owner@1234".toCharArray());SubjectStore store=new SubjectStore(dir);check(store.ensureOopSubject("T1"),"OOP subject initializes once");expect(IllegalArgumentException.class,()->store.add(new Subject(Subject.OOP_ID,"Duplicate","","T1",true,Instant.now())),"duplicate subject ID rejected");check(!store.ensureOopSubject("T2")&&store.find(Subject.OOP_ID).getOwnerTeacherId().equals("T1"),"OOP subject seed never overwrites owner");SubjectService service=new SubjectService(store,sessions);expect(SecurityException.class,()->service.createOwned("Denied",""),"unauthenticated subject creation denied");sessions.startTeacher(new TeacherProfile("T1","Owner One"));Subject extra=service.createOwned("Graphics II","Optional subject");check(service.ownedByTeacher().size()==2,"teacher sees only owned subjects including OOP");service.setOwnedActive(extra.getId(),false);sessions.startStudent(new StudentProfile("S1","Student"));check(service.activeForStudent().size()==1,"students do not see inactive subjects");sessions.startTeacher(new TeacherProfile("T1","Owner One"));service.setOwnedActive(extra.getId(),true);sessions.startTeacher(new TeacherProfile("T2","Owner Two"));check(service.ownedByTeacher().isEmpty(),"teacher login lists no unowned OOP subject");expect(SecurityException.class,()->service.setOwnedActive(extra.getId(),false),"cross-owner subject modification denied");expect(SecurityException.class,()->service.select(extra.getId()),"teacher cannot select another owner's subject");sessions.startStudent(new StudentProfile("S1","Student"));check(service.activeForStudent().size()==2,"students see active subjects");service.select(Subject.OOP_ID);check(sessions.current().getSubjectId().equals(Subject.OOP_ID),"explicit subject selection records its ID in session");sessions.current().clearSubject();expect(SecurityException.class,service::requireSelectedOwnedByActiveSession,"switching subjects clears stale selection context");service.select(extra.getId());check(sessions.current().getSubjectId().equals(extra.getId()),"student can explicitly switch to another active subject");sessions.clear();
        QuestionStore bank=new QuestionStore(dir);Question q=new Question("Q-SUB",SyllabusUnit.UNIT_I,"Objects","Question",List.of("a","b","c","d"),0,"",extra.getId());sessions.startTeacher(new TeacherProfile("T1","Owner One"));service.select(extra.getId());QuestionService qs=new QuestionService(bank,sessions,service);qs.addQuestion(q);sessions.startTeacher(new TeacherProfile("T1","Owner One"));service.select(Subject.OOP_ID);expect(SecurityException.class,()->qs.updateQuestion(new Question("Q-SUB",SyllabusUnit.UNIT_I,"edit","Question",List.of("a","b","c","d"),0,"",Subject.OOP_ID)),"question edits are scoped to teacher-owned selected subject");sessions.startStudent(new StudentProfile("S1","Student"));service.select(extra.getId());StudentQuizService quiz=new StudentQuizService(bank,new ResultStore(dir),sessions,java.time.Clock.systemUTC(),service);check(quiz.availableQuizzes().get(0).getSubjectId().equals(extra.getId())&&quiz.availableQuizzes().get(0).getQuestionCount()==1,"quiz question availability is subject scoped");QuizAttempt attempt=quiz.startQuiz(SyllabusUnit.UNIT_I);QuizResult scoped=quiz.submitAttempt(attempt);check(scoped.getSubjectId().equals(extra.getId())&&scoped.getStudentId().equals("S1"),"submitted result retains selected subject and authenticated student identity");
    }
    private static void migrations(Path dir)throws Exception{
        Files.createDirectories(dir);Path studentsFile=dir.resolve("students.csv");Files.writeString(studentsFile,"student_id,display_name\nOLD-7,Legacy Student\n",StandardCharsets.UTF_8);StudentProfileStore legacyStudents=new StudentProfileStore(dir);check(legacyStudents.authenticate("OLD-7","anything123".toCharArray())==null,"legacy passwordless account cannot log in");expect(IllegalArgumentException.class,()->legacyStudents.claimLegacyProfile("Different Name","OLD-7","NewPass@123".toCharArray(),"NewPass@123".toCharArray()),"legacy account claim requires saved display name");legacyStudents.claimLegacyProfile("Legacy Student","OLD-7","NewPass@123".toCharArray(),"NewPass@123".toCharArray());check(legacyStudents.authenticate("OLD-7","NewPass@123".toCharArray())!=null&&Files.exists(dir.resolve("students.csv.pre-account-migration.bak")),"explicit legacy claim preserves profile and backs up old schema");
        Path qf=dir.resolve("questions.csv");String qline="LEGACY,UNIT_I,Topic,Question,a,b,c,d,0,Explanation";Files.writeString(qf,"question_id,unit,topic,question_text,option_1,option_2,option_3,option_4,correct_answer_index,explanation\n"+qline+"\n",StandardCharsets.UTF_8);QuestionStore qs=new QuestionStore(dir);check(qs.load().getQuestions().get(0).getSubjectId().equals(Subject.OOP_ID),"legacy question loads under OOP subject");qs.add(new Question("NEW",SyllabusUnit.UNIT_I,"Topic","Question",List.of("a","b","c","d"),0,""));check(Files.exists(dir.resolve("questions.csv.pre-subject-migration.bak")),"question schema migration keeps a backup");check(qs.load().getQuestions().size()==2,"question migration preserves legacy question");
        Path rf=dir.resolve("results.csv");String header="attempt_id,student_id,student_display_name,quiz_id,quiz_name,unit,question_count,correct_count,incorrect_count,unanswered_count,percentage,completed_at";String row="OLD-A,S1,Student,PCC202-UNIT-I,Unit I Practice Quiz,UNIT_I,1,1,0,0,100.00,2024-01-01T00:00:00Z";Files.writeString(rf,header+"\n"+row+"\n",StandardCharsets.UTF_8);ResultStore rs=new ResultStore(dir);check(rs.loadAll().getResults().get(0).getSubjectId().equals(Subject.OOP_ID),"legacy result loads under OOP subject");QuizResult r=new QuizResult("NEW-A","S1","Student","PCC202-UNIT-I","Unit I Practice Quiz",SyllabusUnit.UNIT_I,1,1,0,0,new BigDecimal("100.00"),Instant.parse("2024-01-02T00:00:00Z"),Subject.OOP_ID);rs.saveCompleted(r);check(Files.exists(dir.resolve("results.csv.pre-subject-migration.bak")),"result migration keeps a backup");check(rs.loadAll().getResults().size()==2,"result migration preserves historical attempts");check(!Files.readString(rf).contains("correct_answer"),"result records contain no answer key data");
    }
    private static void check(boolean ok,String name){if(!ok)throw new AssertionError("FAILED: "+name);passed++;System.out.println("PASS: "+name);}
    private static void expect(Class<? extends Throwable> type,Throwing action,String name)throws Exception{try{action.run();}catch(Throwable ex){if(type.isInstance(ex)){check(true,name);return;}throw new AssertionError("FAILED: "+name+" (got "+ex+")",ex);}throw new AssertionError("FAILED: "+name+" (no exception)");}
    @FunctionalInterface private interface Throwing{void run()throws Exception;}
}






